do local Players=game:GetService("Players");local UIS=game:GetService("UserInputService");local Lighting=game:GetService("Lighting");local RunService=game:GetService("RunService");local TweenService=game:GetService("TweenService");local LocalPlayer=Players.LocalPlayer;local Notify;task.defer(function() Notify=_G.__AdminNotify;end);local function toast(k,m) if Notify then Notify[k](m);end end local Commands={};Commands.list={};local function findPlayer(name) if  not name then return nil;end name=name:lower();for _,p in ipairs(Players:GetPlayers()) do if (p.Name:lower():sub(1, #name)==name) then return p;end end end local function getHRP(player) local c=player and player.Character ;return c and c:FindFirstChild("HumanoidRootPart") ;end local function getHuman(player) local c=player and player.Character ;return c and c:FindFirstChildOfClass("Humanoid") ;end Commands.list['help']=function(sender,args) local names={};for k in pairs(Commands.list) do table.insert(names,k);end table.sort(names);toast("info",table.concat(names,"  |  "));end;Commands.list['unload']=function() end;Commands.list['noclip']=function(sender,args) local char=LocalPlayer.Character;if  not char then return;end if char:FindFirstChild("__noclip") then char.__noclip:Destroy();toast("info","Noclip off");return;end local tag=Instance.new("BoolValue");tag.Name="__noclip";tag.Parent=char;local conn;conn=RunService.Stepped:Connect(function() if  not tag.Parent then conn:Disconnect();return;end for _,p in ipairs(char:GetDescendants()) do if p:IsA("BasePart") then p.CanCollide=false;end end end);toast("success","Noclip on");end;Commands.list['speed']=function(sender,args) local v=tonumber(args[1]);if  not v then toast("warn","speed <number>");return;end local h=getHuman(LocalPlayer);if h then h.WalkSpeed=v;toast("success","Speed → "   .. v );end end;Commands.list['jump']=function(sender,args) local v=tonumber(args[1]);if  not v then toast("warn","jump <number>");return;end local h=getHuman(LocalPlayer);if  not h then return;end if h.UseJumpPower then h.JumpPower=v;else h.JumpHeight=v;end toast("success","Jump → "   .. v );end;Commands.list['fly']=function(sender,args) local char=LocalPlayer.Character;local hrp=getHRP(LocalPlayer);if ( not char or  not hrp) then return;end if char:FindFirstChild("__flyActive") then char.__flyActive:Destroy();toast("info","Fly off");return;end local tag=Instance.new("BoolValue");tag.Name="__flyActive";tag.Parent=char;local bv=Instance.new("BodyVelocity");bv.Velocity=Vector3.zero;bv.MaxForce=Vector3.new(100000,100000,100000);bv.Parent=hrp;local bg=Instance.new("BodyGyro");bg.MaxTorque=Vector3.new(100000,100000,100000);bg.CFrame=hrp.CFrame;bg.Parent=hrp;local speed=tonumber(args[1]) or 50 ;local cam=workspace.CurrentCamera;local conn;conn=RunService.Heartbeat:Connect(function() if  not tag.Parent then bv:Destroy();bg:Destroy();conn:Disconnect();return;end local dir=Vector3.zero;if UIS:IsKeyDown(Enum.KeyCode.W) then dir+=cam.CFrame.LookVector end if UIS:IsKeyDown(Enum.KeyCode.S) then dir-=cam.CFrame.LookVector end if UIS:IsKeyDown(Enum.KeyCode.A) then dir-=cam.CFrame.RightVector end if UIS:IsKeyDown(Enum.KeyCode.D) then dir+=cam.CFrame.RightVector end if UIS:IsKeyDown(Enum.KeyCode.Space) then dir+=Vector3.yAxis end if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then dir-=Vector3.yAxis end bv.Velocity=((dir.Magnitude>0) and (dir.Unit * speed)) or Vector3.zero ;bg.CFrame=cam.CFrame;end);toast("success","Fly on  (speed "   .. speed   .. ")  —  run fly again to stop" );end;Commands.list['unfly']=function(sender,args) local char=LocalPlayer.Character;if (char and char:FindFirstChild("__flyActive")) then char.__flyActive:Destroy();toast("info","Fly off");end end;Commands.list["goto"]=function(sender,args) local t=findPlayer(args[1]);if  not t then toast("warn","Player not found");return;end local hrp=getHRP(LocalPlayer);local tHRP=getHRP(t);if (hrp and tHRP) then hrp.CFrame=tHRP.CFrame * CFrame.new(0,4,0) ;toast("success","Teleported to "   .. t.Name );end end;Commands.list['heal']=function(sender,args) local h=getHuman(LocalPlayer);if h then h.Health=h.MaxHealth;toast("success","Healed");end end;Commands.list['god']=function(sender,args) local h=getHuman(LocalPlayer);if  not h then return;end if h:GetAttribute("__godActive") then h:SetAttribute("__godActive",nil);h.MaxHealth=100;h.Health=100;toast("info","God off");else h:SetAttribute("__godActive",true);h.MaxHealth=1000000000;h.Health=1000000000;toast("success","God on");end end;Commands.list['fov']=function(sender,args) local v=tonumber(args[1]);if  not v then toast("warn","fov <number>");return;end workspace.CurrentCamera.FieldOfView=math.clamp(v,1,120);toast("success","FOV → "   .. math.clamp(v,1,120) );end;Commands.list['time']=function(sender,args) local v=tonumber(args[1]);if ( not v or (v<0) or (v>24)) then toast("warn","time <0-24>");return;end Lighting.ClockTime=v;toast("success","Time → "   .. v );end;Commands.list['fullbright']=function(sender,args) if Lighting:GetAttribute("__fbOn") then Lighting:SetAttribute("__fbOn",nil);Lighting.Brightness=Lighting:GetAttribute("__fbB") or 1 ;Lighting.Ambient=Lighting:GetAttribute("__fbA") or Color3.new() ;Lighting.OutdoorAmbient=Lighting:GetAttribute("__fbOA") or Color3.fromRGB(128,128,128) ;toast("info","Fullbright off");else Lighting:SetAttribute("__fbOn",true);Lighting:SetAttribute("__fbB",Lighting.Brightness);Lighting:SetAttribute("__fbA",Lighting.Ambient);Lighting:SetAttribute("__fbOA",Lighting.OutdoorAmbient);Lighting.Brightness=2;Lighting.Ambient=Color3.fromRGB(255,255,255);Lighting.OutdoorAmbient=Color3.fromRGB(255,255,255);toast("success","Fullbright on");end end;Commands.list['resetcam']=function(sender,args) workspace.CurrentCamera.CameraType=Enum.CameraType.Custom;workspace.CurrentCamera.FieldOfView=70;toast("success","Camera reset");end;Commands.list['printplayers']=function(sender,args) local names={};for _,p in ipairs(Players:GetPlayers()) do table.insert(names,p.Name   .. "("   .. p.UserId   .. ")" );end toast("info",table.concat(names,"  "));end;local _espConnections={};local _espBoxes={};local ESP_COLOR_ENEMY=Color3.fromRGB(255,60,60);local ESP_COLOR_TEAM=Color3.fromRGB(60,220,100);local function removeESP(userId) if _espConnections[userId] then _espConnections[userId]:Disconnect();_espConnections[userId]=nil;end if _espBoxes[userId] then for _,obj in ipairs(_espBoxes[userId]) do if (obj and obj.Parent) then obj:Destroy();end end _espBoxes[userId]=nil;end end local function buildESP(player) local userId=player.UserId;removeESP(userId);local function refresh(char) if _espBoxes[userId] then for _,obj in ipairs(_espBoxes[userId]) do if (obj and obj.Parent) then obj:Destroy();end end end _espBoxes[userId]={};if  not char then return;end local cam=workspace.CurrentCamera;local isTeam=player.Team==LocalPlayer.Team ;local color=(isTeam and ESP_COLOR_TEAM) or ESP_COLOR_ENEMY ;local box=Instance.new("SelectionBox");box.Adornee=char;box.Color3=color;box.LineThickness=0.04;box.SurfaceTransparency=0.85;box.SurfaceColor3=color;box.Parent=cam;table.insert(_espBoxes[userId],box);local bbg=Instance.new("BillboardGui");bbg.Adornee=char:FindFirstChild("HumanoidRootPart") or char:FindFirstChildOfClass("BasePart") ;bbg.Size=UDim2.new(0,120,0,40);bbg.StudsOffset=Vector3.new(0,3,0);bbg.AlwaysOnTop=true;bbg.MaxDistance=1000;bbg.Parent=cam;local nameLabel=Instance.new("TextLabel");nameLabel.Size=UDim2.fromScale(1,0.5);nameLabel.BackgroundTransparency=1;nameLabel.Text=player.Name;nameLabel.TextColor3=color;nameLabel.TextStrokeTransparency=0;nameLabel.TextStrokeColor3=Color3.new();nameLabel.TextSize=13;nameLabel.Font=Enum.Font.GothamBold;nameLabel.TextScaled=false;nameLabel.Parent=bbg;local healthLabel=Instance.new("TextLabel");healthLabel.Size=UDim2.new(1,0,0.5,0);healthLabel.Position=UDim2.fromScale(0,0.5);healthLabel.BackgroundTransparency=1;healthLabel.TextColor3=Color3.fromRGB(200,200,200);healthLabel.TextStrokeTransparency=0;healthLabel.TextStrokeColor3=Color3.new();healthLabel.TextSize=11;healthLabel.Font=Enum.Font.Gotham;healthLabel.TextScaled=false;healthLabel.Parent=bbg;table.insert(_espBoxes[userId],bbg);local hum=char:FindFirstChildOfClass("Humanoid");local hpConn;if hum then healthLabel.Text=math.floor(hum.Health)   .. " / "   .. math.floor(hum.MaxHealth) ;hpConn=hum:GetPropertyChangedSignal("Health"):Connect(function() if (hum and hum.Parent) then healthLabel.Text=math.floor(hum.Health)   .. " / "   .. math.floor(hum.MaxHealth) ;end end);table.insert(_espBoxes[userId],{Disconnect=function() if hpConn then hpConn:Disconnect();end end});else healthLabel.Text="? / ?";end end refresh(player.Character);_espConnections[userId]=player.CharacterAdded:Connect(function(char) task.wait();refresh(char);end);end Commands.list['esp']=function(sender,args) local sub=args[1] and args[1]:lower() ;if ((sub=="off") or (sub=="remove")) then for uid in pairs(_espConnections) do removeESP(uid);end toast("info","ESP removed");return;end if ((sub=="all") or  not sub) then local any=false;for uid in pairs(_espConnections) do any=true;break;end if any then for uid in pairs(_espConnections) do removeESP(uid);end toast("info","ESP off");else for _,p in ipairs(Players:GetPlayers()) do if (p~=LocalPlayer) then buildESP(p);end end Players.PlayerAdded:Connect(function(p) if (_espConnections[1]~=nil) then if (p~=LocalPlayer) then buildESP(p);end end end);Players.PlayerRemoving:Connect(function(p) removeESP(p.UserId);end);toast("success","ESP on for all players");end return;end local t=findPlayer(sub);if  not t then toast("warn","Player not found");return;end if _espConnections[t.UserId] then removeESP(t.UserId);toast("info","ESP off for "   .. t.Name );else buildESP(t);Players.PlayerRemoving:Connect(function(p) if (p==t) then removeESP(p.UserId);end end);toast("success","ESP on for "   .. t.Name );end end;Commands.list['printplayers']=function(sender,args) local names={};for _,p in ipairs(Players:GetPlayers()) do table.insert(names,p.Name   .. " ("   .. p.UserId   .. ")" );end toast("info",table.concat(names,"  |  "));end;Commands.list['norotate']=function(sender,args) local h=getHuman(LocalPlayer);if h then h.AutoRotate=false;toast("info","AutoRotate off");end end;Commands.list['autorotate']=function(sender,args) local h=getHuman(LocalPlayer);if h then h.AutoRotate=true;toast("info","AutoRotate on");end end;Commands.list['sit']=function(sender,args) local h=getHuman(LocalPlayer);if h then h.Sit=true;end end;Commands.list['respawn']=function(sender,args) LocalPlayer:LoadCharacter();end;return Commands; end
